<?php
declare(strict_types=1);require_once __DIR__.'/includes/functions.php';$error=null;$success=false;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=trim($_POST['email']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Informe um e-mail válido.';else{try{$user=null;$table=null;foreach(['administradores','clientes'] as $t){$q=$pdo->prepare("SELECT id,nome,email FROM {$t} WHERE email=? AND ativo=1 AND senha IS NOT NULL LIMIT 1");$q->execute([$email]);if($user=$q->fetch()){$table=$t;break;}}if($user){$token=bin2hex(random_bytes(32));$hash=hash('sha256',$token);$pdo->prepare("UPDATE {$table} SET token_redefinicao_senha=?,token_redefinicao_expira=DATE_ADD(NOW(),INTERVAL 1 HOUR) WHERE id=?")->execute([$hash,$user['id']]);$link=rtrim(verification_base_url(),'/').'/redefinir-senha.php?token='.urlencode($token);send_smtp_mail($user['email'],'Redefinição de senha — MesaReserva',"Olá, {$user['nome']}!\n\nPara criar uma nova senha, acesse o link válido por 1 hora:\n\n{$link}\n\nSe não solicitou, ignore este e-mail.\nMesaReserva");}$success=true;}catch(Throwable $e){error_log('MesaReserva password reset: '.$e->getMessage());$error='Não foi possível concluir o envio. Confira as configurações SMTP e tente novamente.';}}}
?>
<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Recuperar senha | MesaReserva</title><link rel="stylesheet" href="<?= url('assets/css/style.css') ?>"></head><body class="auth-page"><main class="login-panel"><section class="login-box forgot-box"><a href="<?= url() ?>"><img class="login-logo" src="<?= url('assets/img/logo.png') ?>" alt="MesaReserva"></a><div class="login-welcome"><h1>Esqueceu sua senha?</h1><p>Informe o e-mail da sua conta para receber o link de redefinição.</p></div><?php if($error):?><div class="login-error"><?= e($error) ?></div><?php endif;?><?php if($success):?><div class="alert alert-success">Se o e-mail estiver cadastrado, enviaremos as instruções para redefinir a senha.</div><a class="btn btn-primary" href="<?= url('login.php') ?>">Voltar para entrar</a><?php else:?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="form-group"><label for="email">E-mail cadastrado</label><input id="email" class="form-control" type="email" name="email" required></div><button class="btn btn-primary login-submit" type="submit">Enviar link de redefinição</button></form><?php endif;?><div class="login-links"><a href="<?= url('login.php') ?>">Voltar ao login</a></div></section></main><?php require __DIR__.'/partials/footer-public.php';?></body></html>
